arguments.command:
cat > tests/price_test.sh <<'EOF'
#!/bin/bash
fail=0
[ "$(bash bin/price 500)" = 450 ] || { echo "price 500"; fail=1; }
[ "$(bash bin/price 1000)" = 900 ] || { echo "price 1000"; fail=1; }
[ "$(bash bin/price 999)" = 899 ] || { echo "price 999"; fail=1; }
[ "$(bash bin/quote 999)" = "quote: 899" ] || { echo "quote 999"; fail=1; }
[ "$(bash lib/invoice.sh 999)" = "member total 899" ] || { echo "invoice 999"; fail=1; }
exit $fail
EOF
bash scripts/verify.sh; echo "rc=$?"
sed -i 's|(\$1 \* 90 + 99) / 100|$1 * 90 / 100|' bin/price bin/quote lib/invoice.sh
git diff --stat; bash scripts/verify.sh; echo "rc=$?"
mkdir -p notes; cat > notes/PRC-501.md <<'EOF'
# PRC-501: member price rounded up
- Cause: commit ee322d6 ("tidy up rounding") changed `$1*90/100` to `($1*90+99)/100` (round up) in bin/price, bin/quote, lib/invoice.sh.
- Fix: restore floor division in all three (same logic is duplicated; README says all use the 10%-off round-down rule).
- Tests: added 999 cases for price, quote, invoice to tests/price_test.sh.
EOF

